sys_script_include.script:
var BudgetUtilsCS = Class.create();
BudgetUtilsCS.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	calculateTotalBudget: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new BudgetUtils().calculateTotalBudget(_eventId));
    },

    calculateRemainingBudget: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new BudgetUtils().calculateRemainingBudget(_eventId));
    },

    isBudgetApproved: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new BudgetUtils().isBudgetApproved(_eventId));
    },

    getBudgetDetailsByEvent: function() {
		var _eventId = this.getParameter('sysparm_eventId');
        return JSON.stringify(new BudgetUtils().getBudgetDetailsByEvent(_eventId));
    },

    type: 'BudgetUtilsCS'
});
